def find_perfect_squares(N):
    perfect_squares = []
    for i in range(1, N + 1):
        root = 1
        while root * root < i:
            root += 1
        if root * root == i:
            perfect_squares.append(i)
    return perfect_squares

def count_successful_villagers(N):
    successful_villagers = 0
    for i in range(1, N + 1):
        fruits = i
        layers = 0
        while fruits > 0 and layers < 10:
            layers += 1
            fruits -= layers
        if fruits == 0 and layers <= 10:
            successful_villagers += 1
    return successful_villagers

def count_hurdles(N, K, heights):
    count = 0
    for h in heights:
        if h <= K:
